// @vitest-environment node
/**
 * Golden URLs: `__fixtures__/image-golden.jsonl` was generated by running v8
 * storefronts' vendored v7 `getOptimizedMediaUrl` / `getSrcSet`, unchanged,
 * over Shopify CDN sources. Each config below is the `createImageUrl` a site
 * builds from `shopifyCdn` and `decoCdn`, and must reproduce its URLs byte for
 * byte: no case changes.
 */
import { readFileSync } from "node:fs";
import {
  createImageUrl,
  decoCdn,
  type ImageUrl,
  type ResizeOptions,
  srcSet,
} from "@decocms/blocks/image";
import { describe, expect, it } from "vitest";
import { shopifyCdn } from "./image.ts";

interface Case {
  config: string;
  call: "url" | "srcSet";
  src: string;
  opts?: ResizeOptions & { factors?: number[] };
  expected: string | null;
}

const cases: Case[] = readFileSync(
  new URL("./__fixtures__/image-golden.jsonl", import.meta.url),
  "utf-8",
)
  .split("\n")
  .filter(Boolean)
  .map((line) => JSON.parse(line));

const tanstack = (cdn: Parameters<typeof decoCdn>[0] = {}) =>
  createImageUrl({ providers: [shopifyCdn(), decoCdn({ sources: "all", ...cdn })] });

const CONFIGS: Record<string, ImageUrl> = {
  "tanstack-decoims-high": tanstack({ domain: "decoims.com", quality: "high" }),
  "tanstack-default": tanstack(),
  "tanstack-anchored": tanstack({ stripAssetHosts: "leading" }),
};

describe("golden URLs: each storefront's current helpers, byte for byte", () => {
  it("covers every config, and no case is a changed URL", () => {
    expect(new Set(cases.map((c) => c.config))).toEqual(new Set(Object.keys(CONFIGS)));
    expect(cases.filter((c) => "before" in c)).toEqual([]);
  });

  for (const config of Object.keys(CONFIGS)) {
    it(config, () => {
      const url = CONFIGS[config];
      const diffs = cases
        .filter((c) => c.config === config)
        .map((c) => ({
          c,
          got:
            c.call === "srcSet"
              ? (srcSet(url, c.src, c.opts ?? {}) ?? null)
              : url(c.src, c.opts as ResizeOptions),
        }))
        .filter(({ c, got }) => got !== c.expected)
        .map(({ c, got }) => ({
          call: c.call,
          src: c.src,
          opts: c.opts,
          expected: c.expected,
          got,
        }));
      expect(diffs).toEqual([]);
    });
  }
});

describe("shopifyCdn", () => {
  it("sets width, height when given, and crop=center; keeps a height already there", () => {
    const u = createImageUrl({ providers: [shopifyCdn()] });
    expect(u("https://cdn.shopify.com/s/a.jpg?v=1", { width: 300, height: 200 })).toBe(
      "https://cdn.shopify.com/s/a.jpg?v=1&width=300&height=200&crop=center",
    );
    expect(u("https://cdn.shopify.com/s/a.jpg?height=50", { width: 300 })).toBe(
      "https://cdn.shopify.com/s/a.jpg?height=50&width=300&crop=center",
    );
    expect(u.isOptimizable("https://images.example.com/a.jpg")).toBe(false);
  });

  it("is the ./image subpath's only export", async () => {
    const pkg = JSON.parse(readFileSync(new URL("../package.json", import.meta.url), "utf-8"));
    expect(pkg.exports["./image"]).toEqual({
      types: "./dist/image.d.ts",
      source: "./src/image.ts",
      default: "./dist/image.js",
    });
    expect(Object.keys(await import("./image.ts"))).toEqual(["shopifyCdn"]);
  });
});
